const a={title:"TripReel - Aplikasi Animasi Perjalanan Percuma: Tukar Foto kepada Video Cantik",description:"Cipta video perjalanan yang menakjubkan dengan peta animasi dan laluan penerbangan. Aplikasi animasi perjalanan percuma dengan pemetaan laluan globe 3D. Tukar foto anda kepada video perjalanan cantik secara automatik. Privasi dahulu, berfungsi luar talian.",keywords:"aplikasi animasi perjalanan, aplikasi animasi peta perjalanan, aplikasi animasi laluan perjalanan, aplikasi animasi penerbangan, pembuat video perjalanan, video perjalanan automatik, peta perjalanan animasi, animasi laluan penerbangan, animasi perjalanan, animasi globe, video rekap perjalanan, foto ke video, sorotan perjalanan, aplikasi perjalanan percuma, pembuat video luar talian, aplikasi perjalanan peribadi, video gulungan kamera"},n={logoAlt:"Logo TripReel",appName:"TripReel",howItWorks:"Cara Ia Berfungsi",video:"Video",features:"Ciri-ciri",theApp:"Aplikasi"},e={badge:"Tukarkan Foto Kepada Cerita Perjalanan",title1:"Galeri Foto Anda,",title2:"Dimanfaatkan Sepenuhnya",description:"TripReel secara automatik mencipta video perjalanan yang cantik daripada lokasi foto anda. Saksikan perjalanan anda menjadi hidup dengan peta laluan animasi yang menakjubkan dan laluan penerbangan merentasi glob 3D, sambil data anda kekal peribadi dan selamat.",secure:"100% Selamat",worksOffline:"Berfungsi Luar Talian",globeAlt:"Animasi Glob TripReel"},i={title:"Cara Ia Berfungsi",subtitle:"Tiga langkah mudah untuk mencipta video perjalanan sempurna anda",step1:{title:"Benarkan Akses Foto",description:"Berikan TripReel akses kepada perpustakaan foto anda. Aplikasi hanya membaca metadata lokasi, tidak lebih."},step2:{title:"Pengesanan Perjalanan Automatik",description:"TripReel menganalisis metadata lokasi dan mencari perjalanan anda dengan bijak berdasarkan tarikh dan lokasi."},step3:{title:"Jana Video Anda",description:"Saksikan perjalanan anda terbentang pada animasi glob yang cantik, bersedia untuk dikongsi di media sosial."}},t={title:"Lihat Keajaibannya",subtitle:"Lihat bagaimana TripReel mengubah perpustakaan foto anda menjadi video perjalanan yang menakjubkan",caption:"Beginilah rupa video perjalanan akhir anda"},r={title:"Semua Yang Anda Perlukan",subtitle:"Ciri-ciri berkuasa direka untuk pengembara moden",twoTap:{title:"Video Perjalanan Dua Ketukan",description:"Cipta video rekap perjalanan yang menakjubkan daripada perpustakaan foto anda hanya dengan dua ketukan. Tiada pengeditan diperlukan."},smartTrip:{title:"Pengesanan Perjalanan Pintar",description:"Secara automatik mencari dan mengumpulkan perjalanan anda dengan menganalisis tarikh dan metadata lokasi daripada foto anda."},globe:{title:"Animasi Glob yang Cantik",description:"Saksikan perjalanan anda menjadi hidup dengan glob 3D yang menakjubkan menunjukkan laluan perjalanan animasi dan laluan penerbangan anda di seluruh dunia."},privacy:{title:"Privasi Utama",description:"Semua diproses pada peranti anda. Foto anda tidak pernah meninggalkan telefon anda. Berfungsi dalam mod pesawat."},customStyles:{title:"Gaya Tersuai",description:"Pilih daripada pelbagai gaya bumi dan penyesuaian untuk sepadan dengan estetik anda dan jadikan setiap video unik."},manualControl:{title:"Kawalan Manual",description:"Anda boleh menambah perjalanan baharu sepenuhnya secara manual jika perkhidmatan lokasi tidak diaktifkan pada peranti anda."}},l={title:"Idea Video Kreatif",subtitle:"Dapatkan inspirasi dengan apa yang boleh anda cipta menggunakan TripReel. Daripada percutian hujung minggu singkat hingga pengembaraan setahun penuh, cipta video perjalanan yang menakjubkan untuk setiap perjalanan.",description:"Sama ada anda mencipta animasi peta perjalanan, mendokumentasikan laluan penerbangan, atau membuat rekap perjalanan akhir tahun, TripReel memudahkan untuk mengubah kenangan anda menjadi video yang boleh dikongsi.",ideas:{yearRecap:{title:"Rekap Perjalanan 2025",description:"Cipta video rekap perjalanan tahunan 2025 anda secara automatik"},europeRoadTrip:{title:"Perjalanan Jalan Raya Eropah",description:"Pamerkan pengembaraan Eropah anda dengan peta laluan animasi"},southeastAsia:{title:"Perjalanan Asia Tenggara",description:"Visualkan laluan backpacking anda merentasi pelbagai negara"},japanRail:{title:"Perjalanan Keretapi Jepun",description:"Cipta video peta laluan keretapi anda di seluruh Jepun"},crossCountry:{title:"Merentasi Amerika Syarikat",description:"Tukarkan perjalanan jalan raya Amerika anda menjadi video laluan epik"},islandHopping:{title:"Melompat Pulau",description:"Tunjukkan perjalanan pulau ke pulau anda dengan animasi 3D yang menakjubkan"},worldTour:{title:"Montaj Lawatan Dunia",description:"Pelbagai perjalanan menjadi satu video perjalanan global yang menakjubkan"},travelPlans:{title:"Rancangan Perjalanan 2026",description:"Visualkan dan rancang pengembaraan perjalanan anda yang menarik untuk 2026"},lifetimeTravel:{title:"Kisah Perjalanan Seumur Hidup",description:"Cipta video yang mempamerkan semua perjalanan seumur hidup anda"},regionalExplorer:{title:"Penjelajah Wilayah",description:"Petakan pengembaraan anda merentasi negeri, wilayah, dan rantau"},festivalCircuit:{title:"Litar Festival",description:"Petakan perjalanan festival muzik dan acara anda"},bikeRoutes:{title:"Percutian Bandar Saya",description:"Pamerkan semua pelarian bandar anda"}}},d={title:"Aplikasi",subtitle:"Kini tersedia di App Store",alt1:"Video Perjalanan Automatik - Cipta video menakjubkan dalam beberapa saat",alt2:"Pengesanan Lokasi Foto - Menggunakan metadata foto anda",alt3:"Pengesanan Perjalanan - Mengumpulkan perjalanan anda secara automatik",alt4:"Video Bumi yang Cantik - Animasi glob perjalanan anda",alt5:"Gaya Tersuai - Peribadikan video perjalanan anda"},s={comingSoon:"Akan Datang",androidTitle:"Aplikasi Android Akan Datang!",androidMessage:'Versi Android belum tersedia tetapi akan datang tidak lama lagi. Hantar mesej kepada saya di <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> dan saya akan memberitahu anda apabila ia sudah sedia!',gotIt:"Faham!"},p={title:"Soalan Lazim",subtitle:"Semua yang perlu anda ketahui tentang TripReel",q1:{question:"Bolehkah saya benar-benar menggunakan aplikasi sepenuhnya dalam mod pesawat?",answer:"Ya! Untuk pengguna premium, aplikasi boleh digunakan sepenuhnya luar talian dalam mod pesawat tanpa had. Untuk pengguna bukan premium, sesetengah ciri disokong iklan yang mungkin memerlukan pengaktifan internet sementara, tetapi untuk pengguna premium tiada iklan dan aplikasi boleh digunakan sepenuhnya dalam mod pesawat."},q2:{question:"Saya telah naik taraf ke Premium, bagaimana untuk mengeluarkan tanda air?",answer:"Ramai orang bertanya aplikasi apa yang digunakan untuk mencipta video ini, jadi, selepas naik taraf ke premium, anda mempunyai pilihan untuk menambah versi tanda air yang lebih kecil (dengan hanya nama aplikasi) atau mengeluarkannya sepenuhnya jika anda mahu."},q3:{question:"Adakah data foto saya selamat dan peribadi?",answer:"Sudah tentu! TripReel hanya membaca metadata lokasi daripada foto anda - kami tidak pernah mengakses, menyimpan, atau menghantar kandungan foto sebenar. Semua pemprosesan berlaku secara tempatan pada peranti anda, dan tiada data pernah meninggalkan telefon anda. Anda boleh mengesahkan ini dengan menggunakan aplikasi dalam mod pesawat - ia berfungsi dengan sempurna luar talian!"},q4:{question:"Bagaimana jika foto saya tidak mempunyai data lokasi?",answer:"Tiada masalah! Jika perkhidmatan lokasi tidak diaktifkan semasa anda mengambil foto, anda boleh mencipta perjalanan secara manual dan menambah lokasi sendiri. Aplikasi memberi anda kawalan penuh untuk menyesuaikan garis masa perjalanan anda."},q5:{question:"Bagaimana aplikasi mengesan perjalanan saya secara automatik?",answer:"TripReel menganalisis metadata lokasi dan cap masa daripada foto anda untuk mengenal pasti dengan bijak bila dan di mana anda melancong. Ia mengumpulkan lokasi dan tarikh berdekatan bersama untuk mengesan perjalanan anda secara automatik tanpa kerja manual diperlukan."},q6:{question:"Bolehkah saya menyesuaikan penampilan video saya?",answer:"Ya! Anda boleh memilih daripada pelbagai gaya bumi dan menyesuaikan pelbagai aspek video perjalanan animasi anda untuk sepadan dengan estetik peribadi anda. Pengguna premium mendapat akses kepada gaya animasi laluan tambahan, tema peta, dan pilihan laluan penerbangan."},q7:{question:"Adakah saya perlu mencipta akaun?",answer:"Tiada akaun diperlukan! TripReel berfungsi serta-merta selepas dimuat turun. Tiada pendaftaran, tiada log masuk, dan tiada maklumat peribadi diperlukan. Hanya muat turun aplikasi dan mula cipta video perjalanan anda dengan segera."},q8:{question:"Mengapa ada lokasi yang hilang daripada perjalanan saya?",answer:"Aplikasi hanya boleh berfungsi dengan data yang tersedia, jadi pertama sekali anda memerlukan sekurang-kurangnya beberapa foto di lokasi tersebut. Kedua, anda perlu memastikan anda mengaktifkan data lokasi semasa berada di sana. Ketiga, kadang-kadang penerimaan GPS yang rendah boleh menyebabkan data lokasi yang salah. Jika anda telah menolak semua ini dan lokasi anda masih tidak muncul, anda boleh menambah lokasi tersebut secara manual daripada Trips Overview > butang Edit. Sila gunakan Contact juga untuk melaporkan isu tersebut."},q9:{question:"Di mana boleh saya kongsi video hebat saya?",answer:"Sudah tentu, anda juga boleh kongsinya di semua platform sosial. Untuk lebih sesuai dengan platform, aplikasi membenarkan nisbah aspek yang berbeza untuk video anda."},q10:{question:"Di mana boleh saya laporkan pepijat?",answer:"Hanya hubungi saya terus di marian@qod.ee, terangkan secara ringkas apa masalahnya."}},u={title:"Sokongan E-mel",description:"Jika anda mempunyai sebarang maklum balas atau menghadapi sebarang masalah, sila hubungi saya terus di e-mel ini dan saya akan membaca dan mengendalikan permintaan anda secepat mungkin secara peribadi. Terima kasih kerana menggunakan aplikasi!",close:"Tutup"},k={default:{title:"🍪 Kuki",message:"Kami menggunakan kuki di laman TripReel untuk meningkatkan pengalaman anda. Tiada data peribadi dikumpul.",accept:"Terima",decline:"Tolak",details:"Butiran"},theme:{title:"🍪 Kuki",message:"🌙 Untuk menyimpan pilihan tema anda, anda perlu menerima kuki penting di laman TripReel. Tanpa mereka, pilihan tema anda tidak dapat disimpan.",accept:"Terima",decline:"Tolak",details:"Butiran"}},m={privacy:"Dasar Privasi Aplikasi",cookies:"Dasar Kuki Laman Web",contact:"Hubungi",cookiePreferences:"Pilihan Kuki",madeWith:"Dibuat dengan",forTravelers:"untuk pengembara di seluruh dunia",copyright:"© {{year}} TripReel."},o={title:"Bersedia Kongsi Perjalanan Anda?",description:"Muat turun TripReel hari ini dan tukarkan galeri kamera anda menjadi video perjalanan yang cantik dengan peta dan laluan animasi. Pengembaraan anda layak disambut.",features:"Percuma untuk dimuat turun • Pantas & Mudah • Privasi terjamin"},g={title:"Tentang TripReel",subtitle:"Pembuat video sorotan perjalanan profesional dan aplikasi animator laluan perjalanan",howItWorks:{title:"Cara Aplikasi Ringkasan Perjalanan Kami Berfungsi",description:"Aplikasi animasi perjalanan menggunakan algoritma pintar untuk mengimbas data GPS foto anda dan secara automatik mengesan perjalanan anda. Animator laluan perjalanan kemudian mencipta animasi laluan perjalanan yang lancar dan sinematik yang menunjukkan laluan anda merentas bandar, negara dan benua. Sama ada anda membuat video sorotan perjalanan hujung minggu yang cepat atau video ringkasan perjalanan setahun penuh, aplikasi peta perjalanan beranimasi menjadikannya mudah."},customization:{title:"Penyesuaian Meluas untuk Video Animasi Perjalanan Anda",description:"Aplikasi pembuat cerita perjalanan menawarkan pilihan penyesuaian peringkat profesional untuk menjadikan video peta perjalanan beranimasi anda benar-benar unik:",features:{videoQuality:"Pilih antara 30 FPS, 60 FPS, atau premium 90 FPS untuk animasi laluan perjalanan licin seperti sutera dalam video sorotan perjalanan anda",bitrate:"Laraskan kualiti video (kadar bit) dari normal ke tinggi untuk video perjalanan peta jernih kristal tanpa artifak visual",earthStyles:"Pilih daripada pelbagai gaya bumi yang menakjubkan termasuk Realistik, Lampu Malam, Peta Siang dan paparan Satelit untuk video peta perjalanan beranimasi anda",borders:"Togol sempadan negara pada animator laluan perjalanan anda dengan warna dan ketebalan boleh disesuaikan untuk visualisasi geografi yang dipertingkatkan",aspectRatios:"Cipta video animasi perjalanan dalam format Menegak (9:16), Skrin Lebar (16:9), Pawagam (2.35:1), atau Persegi (1:1) sempurna untuk Instagram, TikTok, YouTube, dan platform sosial lain",tripSpeed:"Kawal kelajuan animator laluan perjalanan antara lokasi (sehingga 3500 km/s) untuk mencipta video ringkasan perjalanan yang dinamik atau santai",pauseDuration:"Laraskan tempoh jeda di setiap lokasi (0.5-5 saat) untuk menonjolkan destinasi penting dalam video sorotan perjalanan anda",locationLabels:"Paparkan label Bandar, Wilayah, dan/atau Negara pada video peta perjalanan beranimasi anda untuk memberikan konteks kepada perjalanan anda",pathDisplay:"Togol sama ada anda mahu memaparkan semua laluan perjalanan terdahulu atau hanya perjalanan semasa dalam animasi laluan perjalanan anda"}}},b={meta:a,header:n,hero:e,howItWorks:i,videoSection:t,features:r,videoIdeas:l,screenshots:d,appStore:s,faq:p,contact:u,cookieBanner:k,footer:m,cta:o,about:g};export{g as about,s as appStore,u as contact,k as cookieBanner,o as cta,b as default,p as faq,r as features,m as footer,n as header,e as hero,i as howItWorks,a as meta,d as screenshots,l as videoIdeas,t as videoSection};
